def bfs(state, start):
    size = state["size"]
    walls = set(map(tuple, state["walls"]))
    dist = {tuple(start): (0, "STAY")}
    todo = [tuple(start)]
    while todo:
        nxt = []
        for (x, y) in todo:
            for d, (dx, dy) in (("N", (0, -1)), ("E", (1, 0)), ("S", (0, 1)), ("W", (-1, 0))):
                n = (x + dx, y + dy)
                if 0 <= n[0] < size and 0 <= n[1] < size and n not in walls and n not in dist:
                    dist[n] = (dist[(x, y)][0] + 1, d if (x, y) == tuple(start) else dist[(x, y)][1])
                    nxt.append(n)
        todo = nxt
    return dist

def play(state):
    me = bfs(state, state["me"])
    c = [(me[tuple(s)][0], me[tuple(s)][1]) for s in state["seeds"] if tuple(s) in me]
    return min(c)[1] if c else "STAY"

